"""Adapter for the partner settlement API."""

from decimal import Decimal


def _to_fractional_units(amount_cents: int) -> float:
    # Decimal keeps the cents-to-units conversion exact before the final
    # float cast, avoiding binary-float rounding artifacts (e.g. 549 -> 5.49
    # rather than 5.4899999999999998).
    return float(Decimal(amount_cents) / 100)


def to_partner_payload(order: dict) -> dict:
    return {
        "orderId": order["id"],
        "partner": order["partner_id"],
        "amount": _to_fractional_units(order["amount_cents"]),
    }

